package dev.veltraph.client.observation.nativeinput;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Pure identity/order model. Marker objects are not native source or Root authority. */
final class NativeToggleReturnTraceTest {
 private static final class Call implements AutoCloseable {
  final Object source=new Object(),actor=new Object(),supplier=new Object(),nativeField=new Object();final boolean requested,before;
  final NativeToggleReturnTrace trace;boolean closed;NativeToggleReturnTrace.Super inner;NativeToggleReturnTrace.Field field;
  Call(boolean requested,boolean before){this.requested=requested;this.before=before;trace=NativeToggleReturnTrace.begin(source,actor,requested,before,supplier);assertNotNull(trace);}
  void mode(boolean value){var query=trace.modeEntered(actor,supplier);assertNotNull(query);trace.modeReturned(query,value,true);}
  void field(boolean value){inner=trace.superEntered(actor,value);assertNotNull(inner);field=trace.fieldEntered(inner,nativeField,actor,value);assertNotNull(field);trace.fieldReturned(field,nativeField,actor,value,true);trace.superReturned(inner,true);}
  NativeToggleReturnTrace.Return finish(boolean held,boolean normal){closed=true;return trace.outerReturned(source,actor,requested,held,normal);}
  public void close(){if(!closed){closed=true;trace.outerReturned(source,actor,requested,before,false);}}
 }
 @Test void modeFalseUsesRequestedValueForAllHeldStates(){for(boolean requested:new boolean[]{false,true})for(boolean before:new boolean[]{false,true})try(var c=new Call(requested,before)){c.mode(false);c.field(requested);var result=c.finish(requested,true);assertNotNull(result);assertTrue(result.completed());assertTrue(result.current());assertFalse(result.mode());assertEquals(requested,result.held());assertTrue(result.hasField());assertSame(c.nativeField,result.fieldToken());}}
 @Test void modeTruePressTogglesActualBeforeHeld(){for(boolean before:new boolean[]{false,true})try(var c=new Call(true,before)){c.mode(true);c.field(!before);var result=c.finish(!before,true);assertNotNull(result);assertTrue(result.current());assertTrue(result.mode());assertEquals(!before,result.held());assertSame(c.nativeField,result.fieldToken());}}
 @Test void modeTrueReleaseCompletesWithoutSuperOrField(){for(boolean before:new boolean[]{false,true})try(var c=new Call(false,before)){c.mode(true);var result=c.finish(before,true);assertNotNull(result);assertTrue(result.current());assertTrue(result.completed());assertTrue(result.mode());assertEquals(before,result.held());assertFalse(result.hasField());assertNull(result.fieldToken());}}
 @Test void noSourceOrSupplierCannotStartAQuery(){assertNull(NativeToggleReturnTrace.begin(null,new Object(),true,false,new Object()));assertNull(NativeToggleReturnTrace.begin(new Object(),null,true,false,new Object()));assertNull(NativeToggleReturnTrace.begin(new Object(),new Object(),true,false,null));}
 @Test void beginDoesNotInvokeTheModeSupplier(){var count=new java.util.concurrent.atomic.AtomicInteger();java.util.function.BooleanSupplier supplier=()->{count.incrementAndGet();throw new AssertionError("Model cannot query source");};var source=new Object();var actor=new Object();var trace=NativeToggleReturnTrace.begin(source,actor,false,false,supplier);assertNotNull(trace);assertEquals(0,count.get());assertNull(trace.outerReturned(source,actor,false,false,false));assertEquals(0,count.get());}
 @Test void outerNormalReturnWithoutTheActualQueryFails(){try(var c=new Call(true,false)){assertNull(c.finish(true,true));}}
 @Test void wrongModeSupplierPoisonsTheTrace(){try(var c=new Call(true,false)){assertNull(c.trace.modeEntered(c.actor,new Object()));assertNull(c.finish(false,true));}}
 @Test void wrongModeActorPoisonsTheTrace(){try(var c=new Call(true,false)){assertNull(c.trace.modeEntered(new Object(),c.supplier));assertNull(c.finish(false,true));}}
 @Test void modeQueryCanOnlyEnterOnce(){try(var c=new Call(true,false)){var query=c.trace.modeEntered(c.actor,c.supplier);assertNotNull(query);assertNull(c.trace.modeEntered(c.actor,c.supplier));c.trace.modeReturned(query,false,true);assertNull(c.finish(true,true));}}
 @Test void duplicateQueryReturnPoisonsTheTrace(){try(var c=new Call(true,false)){var query=c.trace.modeEntered(c.actor,c.supplier);c.trace.modeReturned(query,false,true);c.trace.modeReturned(query,false,true);assertNull(c.finish(true,true));}}
 @Test void failedModeQueryNeverProducesANormalReturn(){try(var c=new Call(true,false)){var query=c.trace.modeEntered(c.actor,c.supplier);c.trace.modeReturned(query,false,false);assertNull(c.finish(true,true));}}
 @Test void rawFieldWithoutTheSuperSpanFails(){try(var c=new Call(true,false)){c.mode(false);assertNull(c.trace.fieldEntered(null,c.nativeField,c.actor,true));assertNull(c.finish(true,true));}}
 @Test void superBeforeModeNormalReturnFails(){try(var c=new Call(true,false)){assertNull(c.trace.superEntered(c.actor,true));assertNull(c.finish(true,true));}}
 @Test void trueModeReleaseMustNotCallSuper(){try(var c=new Call(false,true)){c.mode(true);assertNull(c.trace.superEntered(c.actor,false));assertNull(c.finish(false,true));}}
 @Test void falseModeSuperMustUseTheRequestedValue(){try(var c=new Call(true,false)){c.mode(false);assertNull(c.trace.superEntered(c.actor,false));assertNull(c.finish(false,true));}}
 @Test void trueModePressMustUseTheInverseBeforeHeld(){try(var c=new Call(true,true)){c.mode(true);assertNull(c.trace.superEntered(c.actor,true));assertNull(c.finish(true,true));}}
 @Test void wrongSuperActorFails(){try(var c=new Call(true,false)){c.mode(false);assertNull(c.trace.superEntered(new Object(),true));assertNull(c.finish(true,true));}}
 @Test void missingNativeFieldTokenFails(){try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);assertNull(c.trace.fieldEntered(inner,null,c.actor,true));assertNull(c.finish(true,true));}}
 @Test void wrongFieldActorOrValueFails(){for(boolean wrongActor:new boolean[]{false,true})try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);assertNull(c.trace.fieldEntered(inner,c.nativeField,wrongActor?new Object():c.actor,wrongActor));assertNull(c.finish(true,true));}}
 @Test void foreignNormalFieldTokenCannotCompleteTheSpan(){try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);var field=c.trace.fieldEntered(inner,c.nativeField,c.actor,true);c.trace.fieldReturned(field,new Object(),c.actor,true,true);c.trace.superReturned(inner,true);assertNull(c.finish(true,true));}}
 @Test void failedActualFieldNormalReturnIsRefused(){try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);var field=c.trace.fieldEntered(inner,c.nativeField,c.actor,true);c.trace.fieldReturned(field,c.nativeField,c.actor,true,false);assertNull(c.finish(true,true));}}
 @Test void superCannotReturnBeforeTheField(){try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);c.trace.superReturned(inner,true);assertNull(c.finish(true,true));}}
 @Test void failedSuperReturnIsRefused(){try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);var field=c.trace.fieldEntered(inner,c.nativeField,c.actor,true);c.trace.fieldReturned(field,c.nativeField,c.actor,true,true);c.trace.superReturned(inner,false);assertNull(c.finish(true,true));}}
 @Test void duplicateFieldOrSuperCallsAreRefused(){for(boolean duplicateField:new boolean[]{false,true})try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);var field=c.trace.fieldEntered(inner,c.nativeField,c.actor,true);c.trace.fieldReturned(field,c.nativeField,c.actor,true,true);if(duplicateField)c.trace.fieldReturned(field,c.nativeField,c.actor,true,true);else assertNull(c.trace.superEntered(c.actor,true));assertNull(c.finish(true,true));}}
 @Test void falseOuterReturnCannotCompleteAField(){try(var c=new Call(true,false)){c.mode(false);c.field(true);assertNull(c.finish(true,false));}}
 @Test void outerSourceActorRequestAndHeldMustAllMatch(){for(int mismatch=0;mismatch<4;mismatch++)try(var c=new Call(true,false)){c.mode(false);c.field(true);c.closed=true;assertNull(c.trace.outerReturned(mismatch==0?new Object():c.source,mismatch==1?new Object():c.actor,mismatch!=2,mismatch!=3,true));}}
 @Test void noFieldReleaseMustPreserveTheHeldState(){try(var c=new Call(false,true)){c.mode(true);assertNull(c.finish(false,true));}}
 @Test void actualReentryPoisonsTheExistingTrace(){try(var c=new Call(true,false)){c.mode(false);assertNull(NativeToggleReturnTrace.begin(new Object(),new Object(),true,false,new Object()));assertNull(c.finish(true,true));}}
 @Test void sourceReentryOfTheSameActorAlsoFails(){try(var c=new Call(false,false)){assertNull(NativeToggleReturnTrace.begin(c.source,c.actor,false,false,c.supplier));assertNull(c.finish(false,true));}}
 @Test void duplicateOuterReturnRetiresThePreviouslyCompletedFact(){try(var c=new Call(false,false)){c.mode(true);var result=c.finish(false,true);assertNotNull(result);assertTrue(result.current());assertNull(c.trace.outerReturned(c.source,c.actor,false,false,true));assertTrue(result.completed());assertFalse(result.current());}}
 @Test void completedOldTraceDoesNotRemoveANewTrace(){NativeToggleReturnTrace.Return old;Call prior=new Call(false,false);try(prior){prior.mode(true);old=prior.finish(false,true);assertNotNull(old);}try(var next=new Call(false,true)){assertNull(prior.trace.outerReturned(prior.source,prior.actor,false,false,true));assertFalse(old.current());next.mode(true);assertNotNull(next.finish(true,true));}}
 @Test void crossThreadCallbackCannotCompleteTheQuery() throws InterruptedException {try(var c=new Call(true,false)){var query=c.trace.modeEntered(c.actor,c.supplier);var thread=new Thread(()->c.trace.modeReturned(query,false,true),"toggle-query-foreign-negative");thread.start();thread.join(2000);assertFalse(thread.isAlive());assertNull(c.finish(true,true));}}
 @Test void queryTokenFromAnotherOuterTraceFails(){NativeToggleReturnTrace.Mode foreign;try(var old=new Call(false,false)){foreign=old.trace.modeEntered(old.actor,old.supplier);old.trace.modeReturned(foreign,true,true);assertNotNull(old.finish(false,true));}try(var c=new Call(false,false)){assertNotNull(c.trace.modeEntered(c.actor,c.supplier));c.trace.modeReturned(foreign,true,true);assertNull(c.finish(false,true));}}
 @Test void superTokenFromAnotherTraceFails(){NativeToggleReturnTrace.Super foreign;try(var old=new Call(true,false)){old.mode(false);old.field(true);foreign=old.inner;assertNotNull(old.finish(true,true));}try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);var field=c.trace.fieldEntered(inner,c.nativeField,c.actor,true);c.trace.fieldReturned(field,c.nativeField,c.actor,true,true);c.trace.superReturned(foreign,true);assertNull(c.finish(true,true));}}
 @Test void fieldTokenFromAnotherTraceFails(){NativeToggleReturnTrace.Field foreign;try(var old=new Call(true,false)){old.mode(false);old.field(true);foreign=old.field;assertNotNull(old.finish(true,true));}try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);assertNotNull(c.trace.fieldEntered(inner,c.nativeField,c.actor,true));c.trace.fieldReturned(foreign,c.nativeField,c.actor,true,true);assertNull(c.finish(true,true));}}
 @Test void fieldReturnActorAndValueMustMatch(){for(boolean wrongActor:new boolean[]{false,true})try(var c=new Call(true,false)){c.mode(false);var inner=c.trace.superEntered(c.actor,true);var field=c.trace.fieldEntered(inner,c.nativeField,c.actor,true);c.trace.fieldReturned(field,c.nativeField,wrongActor?new Object():c.actor,wrongActor,true);assertNull(c.finish(true,true));}}
 @Test void duplicateSuperNormalReturnFails(){try(var c=new Call(true,false)){c.mode(false);c.field(true);c.trace.superReturned(c.inner,true);assertNull(c.finish(true,true));}}

 @Test void selectedEntryRevokesEvenWhenNestedBodyHasNoOpcodes(){try(var c=new Call(false,true)){c.mode(true);c.trace.nestedEntryObserved();assertNull(c.finish(true,true));}}
 @Test void selectedEntryRevokesAlreadyNormallyReturnedFieldWithoutWaitingForNestedCallbacks(){try(var c=new Call(true,false)){c.mode(false);c.field(true);c.trace.nestedEntryObserved();assertNull(c.finish(true,true));}}

}
